public class PolylineTrailPainterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String pixel(java.awt.image.BufferedImage img, int x, int y) {
        if (img == null) {
            return "null-image";
        }
        return String.format("#%06X", img.getRGB(x, y) & 0xFFFFFF);
    }

    static java.awt.image.BufferedImage render(int width, int height) {
        java.awt.image.BufferedImage img = new java.awt.image.BufferedImage(
                width, height, java.awt.image.BufferedImage.TYPE_INT_RGB);
        java.awt.Graphics2D g = img.createGraphics();
        try {
            PolylineTrailPainter.paint(g, width, height);
        } finally {
            g.dispose();
        }
        return img;
    }

    public static void main(String[] args) {
        try {
            java.awt.image.BufferedImage a = render(130, 60);
            check("filled triangle interior (30,37)", "#000000", pixel(a, 30, 37));
            check("filled triangle low interior (20,45)", "#000000", pixel(a, 20, 45));
            check("white above the filled triangle (30,4)", "#FFFFFF", pixel(a, 30, 4));
            check("polyline interior stays white (90,37)", "#FFFFFF", pixel(a, 90, 37));
            check("thick polyline base segment (90,50)", "#000000", pixel(a, 90, 50));
            check("thick polyline right segment (100,30)", "#000000", pixel(a, 100, 30));
            check("closing edge is missing (80,30)", "#FFFFFF", pixel(a, 80, 30));
            check("white between the two shapes (60,30)", "#FFFFFF", pixel(a, 60, 30));
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

